// Recommended event: GA4 knows sign_up and its 'method' parameter
document.querySelector('#signup-form').addEventListener('submit', async (e) => {
  e.preventDefault();
  const res = await fetch('/api/signup', { method: 'POST', body: new FormData(e.target) });
  if (res.ok) {
    gtag('event', 'sign_up', { method: 'email' });
  }
});

// Custom event: nothing in the recommended list fits, so name it yourself
document.querySelector('#pricing-toggle').addEventListener('change', (e) => {
  gtag('event', 'pricing_toggle', {
    billing_period: e.target.checked ? 'yearly' : 'monthly',  // custom parameter
    plan_count: 3                                             // numeric -> custom metric later
  });
});

// Avoid: a parameter that explodes into millions of values
// gtag('event', 'view', { full_url: location.href }); // page_location already exists

// User property: set once, GA4 attaches it to every later event from this user
gtag('set', 'user_properties', {
  plan: 'pro',            // register as user-scoped custom dimension "plan"
  signup_cohort: '2026-Q3'
});

// Event with a parameter you will register as an event-scoped custom dimension
// and one you will register as a custom metric (unit: time)
gtag('event', 'video_watched', {
  video_title: 'Onboarding tour',   // -> custom dimension (event scope)
  watch_seconds: 142                // -> custom metric
});

// Admin > Custom definitions > Create custom dimension
//   Dimension name: Video title | Scope: Event | Event parameter: video_title
// Admin > Custom definitions > Create custom metric
//   Metric name: Watch seconds | Event parameter: watch_seconds | Unit: Time

// gtag('config', 'G-ABC123XYZ', { send_page_view: false }) in the snippet, then:
let previousUrl = document.referrer;   // first virtual view keeps the real referrer

function trackVirtualPage() {
  const url = location.href;
  gtag('event', 'page_view', {
    page_location: url,
    page_title: document.title,   // call after the router has set the title
    page_referrer: previousUrl
  });
  previousUrl = url;
}

// Example with a generic router "afterEach" hook (React Router, Vue Router, etc.)
router.afterEach(() => {
  // wait a tick so <title> and content are updated
  setTimeout(trackVirtualPage, 0);
});
trackVirtualPage();  // the initial load

// Product page
gtag('event', 'view_item', {
  currency: 'EUR', value: 49.0,
  items: [{ item_id: 'SKU_123', item_name: 'Trail Shoe', item_brand: 'Acme',
            item_category: 'Shoes', item_variant: 'blue', price: 49.0, quantity: 1 }]
});

// Add to cart (quantity 2 -> value 98)
gtag('event', 'add_to_cart', {
  currency: 'EUR', value: 98.0,
  items: [{ item_id: 'SKU_123', item_name: 'Trail Shoe', price: 49.0, quantity: 2 }]
});

// Order confirmation page, guarded against reload on the server side
gtag('event', 'purchase', {
  transaction_id: 'T-20260914-0042',  // required: dedupes repeats
  value: 103.0,                        // items 98 + shipping 5
  currency: 'EUR',                     // required with value
  shipping: 5.0, tax: 0.0, coupon: 'SPRING10',
  items: [{ item_id: 'SKU_123', item_name: 'Trail Shoe', price: 49.0, quantity: 2,
            item_category: 'Shoes', item_variant: 'blue' }]
});

// Node.js: confirm a purchase from a payment webhook (api_secret stays on the server)
const MEASUREMENT_ID = 'G-ABC123XYZ';
const API_SECRET = process.env.GA_API_SECRET;

async function sendPurchase(order) {
  const url = `https://www.google-analytics.com/mp/collect?measurement_id=${MEASUREMENT_ID}&api_secret=${API_SECRET}`;
  const body = {
    client_id: order.gaClientId,      // captured in the browser with gtag('get', ...)
    user_id: order.userId,
    timestamp_micros: Date.now() * 1000,
    events: [{
      name: 'purchase',
      params: {
        session_id: order.gaSessionId,  // ties the event to the live session
        engagement_time_msec: 100,
        transaction_id: order.id,
        value: order.total, currency: 'EUR',
        items: order.items.map(i => ({ item_id: i.sku, item_name: i.name, price: i.price, quantity: i.qty }))
      }
    }]
  };
  // swap /mp/collect for /debug/mp/collect while developing to get validation messages
  const res = await fetch(url, { method: 'POST', body: JSON.stringify(body) });
  console.log(res.status);  // 204 on the real endpoint, even for bad payloads
}
